import{_ as o,C as s,o as i,c as r,ak as a,E as e}from"./chunks/framework.DxrHb2fb.js";const b=JSON.parse('{"title":"暗黑模式","description":"","frontmatter":{},"headers":[],"relativePath":"design/dark.md","filePath":"design/dark.md","lastUpdated":1790029076000}'),c={name:"design/dark.md"};function l(h,t,n,p,k,u){const d=s("XhTokenSwatches");return i(),r("div",null,[t[0]||(t[0]=a('<h1 id="暗黑模式" tabindex="-1">暗黑模式 <a class="header-anchor" href="#暗黑模式" aria-label="Permalink to &quot;暗黑模式&quot;">​</a></h1><p>深色不是把浅色反相。皮肤从头到尾只写语义令牌，<code>data-theme=&quot;dark&quot;</code> 换掉的是语义层的取值：面往中性色阶的暗端走、品牌往亮端走、投影换成纯黑加一条浅色上沿。切主题时没有一行组件 CSS 需要改。</p><h2 id="一条轴-七条轴" tabindex="-1">一条轴，七条轴 <a class="header-anchor" href="#一条轴-七条轴" aria-label="Permalink to &quot;一条轴，七条轴&quot;">​</a></h2><p>明暗只是视觉环境七条轴里的一条。它们由同一个控制器维护、投影成根元素上的一组属性，Portal 出去的浮层由 Core 桥接同一组值：</p><div class="language-html vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">html</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">&lt;</span><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">html</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> data-theme</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">=</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;dark&quot;</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> data-brand</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">=</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;xihan&quot;</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> data-density</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">=</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;compact&quot;</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> data-contrast</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">=</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;more&quot;</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> data-motion</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">=</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;reduce&quot;</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> data-transparency</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">=</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;reduce&quot;</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> dir</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">=</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;rtl&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">&gt;</span></span></code></pre></div><table tabindex="0"><thead><tr><th>轴</th><th>取值</th><th>管什么</th></tr></thead><tbody><tr><td><code>data-theme</code></td><td><code>light</code> / <code>dark</code>（偏好可写 <code>system</code>，跟 <code>prefers-color-scheme</code>）</td><td>整套语义取值</td></tr><tr><td><code>data-brand</code></td><td>注册过的品牌 id</td><td>换整套品牌原语梯度</td></tr><tr><td><code>data-density</code></td><td><code>comfortable</code> / <code>compact</code></td><td>控件高度、内距与间隙；不缩字号和字形</td></tr><tr><td><code>dir</code></td><td><code>ltr</code> / <code>rtl</code></td><td>逻辑属性驱动的布局镜像</td></tr><tr><td><code>data-contrast</code></td><td><code>default</code> / <code>more</code>（偏好可写 <code>system</code>）</td><td>加强边界：控件边界升到 3:1、装饰边加深、材质提高不透明度</td></tr><tr><td><code>data-motion</code></td><td><code>default</code> / <code>reduce</code>（偏好可写 <code>system</code>）</td><td>局部关闭位移与缩放动效</td></tr><tr><td><code>data-transparency</code></td><td><code>default</code> / <code>reduce</code>（偏好可写 <code>system</code>）</td><td>磨砂材质切成实体配方</td></tr></tbody></table><p>主题与对比度可以分别落在不同层级：每一层采用最近的 <code>data-theme</code> 与 <code>data-contrast</code>，子主题不撤销祖先的高对比；深色取值块里声明了 <code>color-scheme</code>，嵌套深色区域的原生控件也跟着走。接法见 <a href="/guide/theme#七轴视觉环境运行时">设计令牌与主题 · 七轴视觉环境运行时</a>。</p><h2 id="语义角色怎么翻" tabindex="-1">语义角色怎么翻 <a class="header-anchor" href="#语义角色怎么翻" aria-label="Permalink to &quot;语义角色怎么翻&quot;">​</a></h2><table tabindex="0"><thead><tr><th>角色</th><th>浅色</th><th>深色</th><th>为什么这样</th></tr></thead><tbody><tr><td><code>--xh-bg-page</code></td><td>neutral 50</td><td>neutral 950</td><td>页面底始终比面低一档</td></tr><tr><td><code>--xh-bg-surface</code></td><td>neutral 0</td><td>neutral 900</td><td>面</td></tr><tr><td><code>--xh-bg-surface-raised</code></td><td>neutral 0</td><td>neutral 750</td><td>深色档取半档 750，与淡底差一道明度，抬起面上取淡底的部件静态时才有身形</td></tr><tr><td><code>--xh-bg-subtle</code> → <code>-hover</code> → <code>-active</code></td><td>100 → 200 → 300</td><td>800 → 700 → 650</td><td>交互阶梯在深色档往亮端走</td></tr><tr><td><code>--xh-bg-brand</code> → <code>-hover</code> → <code>-active</code></td><td>brand 600 → 700 → 800</td><td>brand 500 → 400 → 300</td><td>深底上品牌往亮端走才有对比</td></tr><tr><td><code>--xh-bg-brand-subtle</code></td><td>12% 品牌兑 surface</td><td>12% 品牌兑 surface（neutral 900）</td><td>兑 canvas（950）只得 L 0.202，比面还暗；兑面才比面亮一档</td></tr><tr><td><code>--xh-fg-default</code> / <code>-muted</code> / <code>-subtle</code> / <code>-disabled</code></td><td>950 / 600 / 550 / 400</td><td>50 / 400 / 450 / 600</td><td>层级同向，比值逐条核</td></tr><tr><td><code>--xh-fg-on-brand</code></td><td>neutral 0</td><td>neutral 950</td><td>深色档品牌实心底是 brand 500，白字够不着 4.5:1，改深字</td></tr><tr><td><code>--xh-border-default</code> / <code>-subtle</code> / <code>-strong</code></td><td>200 / 100 / 300</td><td>700 / 800 / 600</td><td>装饰边留在 700：往下半档 750 与淡底只差 1.04，热力图格子的描边会与空格连成一片</td></tr><tr><td><code>--xh-border-control</code></td><td>= default</td><td>= default</td><td>控件边界与装饰边同一条规则</td></tr><tr><td><code>--xh-ring-focus</code></td><td>brand 600</td><td>brand 400</td><td>对画布、面、淡底都 ≥ 3:1</td></tr></tbody></table><p>下面这几块画的是当前主题的取值，切换文档站右上角的明暗看它们翻转：</p>',10)),e(d,{prefix:"--xh-bg-",steps:["page","surface","surface-raised","subtle","subtle-hover","subtle-active","brand","brand-subtle"],compact:""}),e(d,{prefix:"--xh-fg-",steps:["default","muted","subtle","disabled","brand"],compact:""}),e(d,{prefix:"--xh-border-",steps:["subtle","default","strong","control-hover"],compact:""}),t[1]||(t[1]=a('<h2 id="深色档的几条特殊规则" tabindex="-1">深色档的几条特殊规则 <a class="header-anchor" href="#深色档的几条特殊规则" aria-label="Permalink to &quot;深色档的几条特殊规则&quot;">​</a></h2><ul><li><strong>投影用纯黑，再加一条浅色上沿。</strong> 中性色阶最暗的一档比页面底还亮，拿它当投影压不出深度；四档海拔在末尾各带 1px 浅色描边把面的上沿提出来，raised / lifted 那条只画上边缘。</li><li><strong>磨砂面同样成立。</strong> frosted 的 0.88 不透明度与 16px 模糊在深底上按黑、白、中灰、页面与品牌背景重新验过正文 4.5:1、焦点环 3:1。</li><li><strong>状态色往亮端走。</strong> 六族语气的实心底、淡底、文字与描边在深色档各有一套取值，<code>--xh-tone-*</code> 的槽名不变。</li><li><strong>overlay 必须能从 canvas 与 surface 中辨认。</strong> 模态遮罩 <code>--xh-bg-overlay</code> 在两套主题下都验过与其下面的面有可见差。</li><li><strong>强制色（forced-colors）另起一套。</strong> 面改由 <code>Canvas</code> / <code>CanvasText</code>，选中改由 <code>Highlight</code> / <code>HighlightText</code>，按钮边改由 <code>ButtonText</code>；不靠颜色的通道（对号、指示条、chevron 转向）在这一档承担全部语义。</li><li><strong>打印取消海拔与材质效果。</strong> 纸上没有屏幕光源，投影与高光只会变成脏灰或无意义亮边：四档海拔置 <code>none</code>，磨砂改实体、关闭滤镜；语义角色只重映射，不动原语。</li></ul><h2 id="怎么接" tabindex="-1">怎么接 <a class="header-anchor" href="#怎么接" aria-label="Permalink to &quot;怎么接&quot;">​</a></h2><ul><li>首屏由服务端直接输出七个已解析属性，客户端接管前不闪。</li><li>用 <code>createVisualEnvironmentController</code> 或框架的 <code>XhConfigProvider</code> / <code>provideXhConfig</code> / <code>&lt;xh-config&gt;</code> 维护状态；局部区域用带 <code>parent</code> 的子控制器，只覆盖自己关心的轴。</li><li>自定义节点想跟着主题走，只写语义令牌与 <code>--xh-tone-*</code>，不写原语：原语在两套主题下是同一个值。</li></ul><h2 id="相关" tabindex="-1">相关 <a class="header-anchor" href="#相关" aria-label="Permalink to &quot;相关&quot;">​</a></h2><ul><li><a href="/design/colors">色彩</a> · <a href="/design/shadow">阴影与材质</a></li><li>指南：<a href="/guide/theme">设计令牌与主题</a> · <a href="/guide/a11y">无障碍与键盘规格</a></li></ul>',6))])}const f=o(c,[["render",l]]);export{b as __pageData,f as default};
